/// Returns the smallest index `k` in `[lo, hi]` such that
/// for all `r < k`, `a[r] < x`, and for all `r >= k` (and `r < hi`), `a[r] >= x`.
pub fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    let mut low = lo;
    let mut high = hi;
    while low < high {
        let mid = low + (high - low) / 2;
        if a[mid] < x {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    low
}

/// Returns the lower‐bound insertion index of `x` in the first 1000 elements of `a`.
/// Assumes `a.len() >= 1000` and that `a[0..1000]` is sorted (non‐decreasing).
pub fn search_1000(a: &[i32], x: i32) -> usize {
    // We only look at indices [0, 1000)
    search_range_helper(a, x, 0, 1000)
}

